    ComputeAffect(this,pkAff,false);
    if (((pkAff->dwFlag != 0) || (pkAff->bApplyOn == '\x13')) || (pkAff->bApplyOn == '\x11')) {
      UpdatePacket(this);
    }
    ComputePoints(this);
    CheckMaximumPoints(this);
